def format_shipping_address(data):
    name = str(data.get('shipping_name', '') or '')
    street = str(data.get('shipping_street', '') or '')
    city = str(data.get('shipping_city', '') or '')
    postcode = str(data.get('shipping_postcode', '') or '')
    return '\n'.join([name, street, f"{city} {postcode}".strip()])
